现在 web-vitals.ts 完整实现（初稿）：

```ts
/**
 * Web Vitals 采集：PerformanceObserver 采集 LCP/CLS/INP，navigation 采集 TTFB，
 * 写入 diagnostics 的环形缓冲供诊断抽屉只读展示。
 *
 * 不引 `web-vitals` 包：规模小、可控，避免包体积与版本策略绑定。
 */

import { getWebVitals, recordVital } from '@/utils/diagnostics'
import type { VitalRecord } from '@/utils/diagnostics'

interface LayoutShiftEntry extends PerformanceEntry {
  hadRecentInput?: boolean
  value?: number
}

interface NavigationEntry extends PerformanceEntry {
  responseStart?: number
}

/** `VITE_PERF_LOG=true` 时把缓冲打印成表格；生产默认静默。 */
function perfLogEnabled(): boolean {
  return import.meta.env.VITE_PERF_LOG === 'true'
}

/**
 * 启动采集，返回清理函数。
 * 各 entry 类型单独 try/catch：浏览器不支持时静默降级，不影响应用。
 */
export function startWebVitals(): () => void {
  if (typeof PerformanceObserver === 'undefined') return () => {}

  const observers: PerformanceObserver[] = []
  let stopped = false
  let clsValue = 0
  let maxInp = 0
  let ttfbValue: number | null = null
  const logEnabled = perfLogEnabled()

  function record(record: VitalRecord): void {
    if (stopped) return
    recordVital(record)
    if (logEnabled) {
      console.table(getWebVitals().map(({ name, value }) => ({ name, value })))
    }
  }

  function observe(type: string, handler: (entry: PerformanceEntry) => void): void {
    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) handler(entry)
      })
      observer.observe({ type, buffered: true })
      observers.push(observer)
    } catch {
      // 旧浏览器不认识该 entry 类型：静默跳过，其余指标继续采集。
    }
  }

  observe('largest-contentful-paint', (entry) => {
    record({ name: 'LCP', value: entry.startTime, at: Date.now() })
  })

  observe('layout-shift', (entry) => {
    const shift = entry as LayoutShiftEntry
    if (shift.hadRecentInput) return
    clsValue += shift.value ?? 0
    record({ name: 'CLS', value: clsValue, at: Date.now() })
  })

  observe('event', (entry) => {
    // INP 近似：event 条目里交互时长最大值；比标准 INP 简化但足够定位慢交互。
    if (entry.duration <= maxInp) return
    maxInp = entry.duration
    record({ name: 'INP', value: entry.duration, at: Date.now() })
  })

  function recordTtfb(entry: NavigationEntry): void {
    if (ttfbValue !== null) return
    ttfbValue = Math.max(0, Math.round((entry.responseStart ?? entry.startTime) - entry.startTime))
    record({ name: 'TTFB', value: ttfbValue, at: Date.now() })
  }

  // 导航条目在 onMounted 时通常已就绪，优先同步读取；observer 只作兜底。
  try {
    const [nav] = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[]
    if (nav) recordTtfb(nav)
  } catch {
    // getEntriesByType 缺失时交给 observer。
  }
  observe('navigation', (entry) => recordTtfb(entry as NavigationEntry))

  return () => {
    if (stopped) return
    stopped = true
    for (const observer of observers) {
      try {
        observer.disconnect()
      } catch {
        // 断开失败不影响卸载。
      }
    }
    observers.length = 0
  }
}
```

注意 LCP 的 entry.startTime 是候选最大内容渲染时间。OK。

关于 INP event entry 的 duration：PerformanceEventTiming duration 是处理时长（含延迟）。近似可接受。

注意 `event` observer 需要 `durationThreshold`? 不需要。Chrome 支持 observe({type:'event', buffered:true})。

测试中 stub PerformanceObserver 的 `observe` 收到 `{type, buffered}`。

现在测试 stub 细节：`new PerformanceObserver(callback)` 时记录 callback；`observe(options)` 记录 type。手动触发需要找到对应 observer。用数组。

注意 web-vitals.spec 和 diagnostics.spec 共用模块级状态（vitest 每个测试文件独立模块注册表，但同文件内共享）。beforeEach resetDiagnostics。

