describe('web-vitals', () => {
  it('LCP 写入诊断环形缓冲，新记录在前', () => {
    stop = startWebVitals()
    emit('largest-contentful-paint', { startTime: 1234 })
    emit('largest-contentful-paint', { startTime: 2345 })
    const rows = getWebVitals()
