content.text:
web-vitals 8/8 绿。现在实现 DiagnosticsDrawer.vue。

需要确定细节：
- `el-drawer` 自动导入（项目使用 unplugin-vue-components）。在 SFC 模板中直接写 `<el-drawer>`。
- 导入 getBuildInfo 等。
- 时间格式化：`formatTime(new Date(record.at).toISOString())`。
- 复制文案。
- 样式 CSS 变量。

组件代码：

```vue
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'

import {
  getBuildInfo,
  getRecentErrors,
  getRecentRequests,
  getRuntimeContext,
  getWebVitals,
} from '@/utils/diagnostics'
import type { BuildInfo, ErrorRecord, RequestRecord, VitalRecord } from '@/utils/diagnostics'
import { formatDuration, formatTime } from '@/utils/format'

const props = defineProps<{
  open: boolean
}>()

const emit = defineEmits<{
  close: []
}>()

const build = ref<BuildInfo>(getBuildInfo())
const runtime = ref(getRuntimeContext())
const requests = ref<RequestRecord[]>([])
const errors = ref<ErrorRecord[]>([])
const vitals = ref<VitalRecord[]>([])

function refresh(): void {
  build.value = getBuildInfo()
  runtime.value = getRuntimeContext()
  requests.value = getRecentRequests()
  errors.value = getRecentErrors()
  vitals.value = getWebVitals()
}

// 抽屉每次打开都重新取快照：关闭期间产生的请求/错误在再次打开时可见。
watch(
  () => props.open,
  (isOpen) => {
    if (isOpen) refresh()
  },
  { immediate: true },
)

function onUpdate(value: boolean): void {
  if (!value) emit('close')
}

function at(ms: number): string {
  return formatTime(new Date(ms).toISOString())
}

function formatVital(record: VitalRecord): string {
  if (record.name === 'CLS') return record.value.toFixed(3)
  return `${Math.round(record.value)}ms`
}

const buildText = computed(() =>
  [
    `版本: ${build.value.version}`,
    `构建时间: ${build.value.buildTime || '未知'}`,
    `Git SHA: ${build.value.gitSha}`,
    `API base: ${build.value.apiBase}`,
    `Mock: ${build.value.mock ? '开启' : '关闭'}`,
  ].join('\n'),
)

const runtimeText = computed(() =>
  [
    `run_id: ${runtime.value.runId ?? '未记录'}`,
    `conversation_id: ${runtime.value.conversationId ?? '未记录'}`,
  ].join('\n'),
)

const requestsText = computed(() =>
  requests.value
    .map((item) => [at(item.at), item.status, formatDuration(item.durationMs), item.requestId || '无 request_id'].join(' · '))
    .join('\n'),
)

const errorsText = computed(() =>
  errors.value
    .map((item) => [at(item.at), item.code, item.message, item.requestId || '无 request_id'].join(' · '))
    .join('\n'),
)

const vitalsText = computed(() =>
  vitals.value.map((item) => [at(item.at), item.name, formatVital(item)].join(' · ')).join('\n'),
)

async function copy(label: string, text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text)
    ElMessage.success(`已复制${label}`)
  } catch {
    ElMessage.warning('复制失败，请手动选中文本后复制')
  }
}
</script>
```

复制按钮：
```html
<button type="button" class="copy" aria-label="复制构建信息" @click="copy('构建信息', buildText)">复制</button>
```
注意 copy 接受 string，computed 传 `.value` 自动解包在模板中就是 buildText 字符串。在模板里 `@click="copy('构建信息', buildText)"` — 模板中 refs 自动解包，所以传的是 string。好。

模板：

```html
<el-drawer
  :model-value="open"
  title="诊断信息"
  size="520px"
  :append-to-body="true"
  @update:model-value="onUpdate"
>
  <p class="hint">
    仅展示排障元数据：id、状态、耗时与版本；不包含 token、消息正文或审批 payload。
  </p>

  <section class="group" aria-label="构建信息">
    <header class="group-head">
      <h3>构建信息</h3>
      <button type="button" class="copy" aria-label="复制构建信息" @click="copy('构建信息', buildText)">
        复制
      </button>
    </header>
    <dl class="kv">
      <div class="kv-row"><dt>版本</dt><dd class="mono">{{ build.version }}</dd></div>
      <div class="kv-row"><dt>构建时间</dt><dd class="mono">{{ build.buildTime || '未知' }}</dd></div>
      <div class="kv-row"><dt>Git SHA</dt><dd class="mono">{{ build.gitSha }}</dd></div>
      <div class="kv-row"><dt>API base</dt><dd class="mono">{{ build.apiBase }}</dd></div>
      <div class="kv-row"><dt>Mock</dt><dd>{{ build.mock ? '开启' : '关闭' }}</dd></div>
    </dl>
  </section>

  <section class="group" aria-label="运行时上下文">
    <header class="group-head">
      <h3>运行时上下文</h3>
      <button ... aria-label="复制运行时上下文" @click="copy('运行时上下文', runtimeText)">复制</button>
    </header>
    <dl class="kv">
      <div class="kv-row"><dt>run_id</dt><dd class="mono">{{ runtime.runId || '未记录' }}</dd></div>
      <div class="kv-row"><dt>conversation_id</dt><dd class="mono">{{ runtime.conversationId || '未记录' }}</dd></div>
    </dl>
  </section>

  <section class="group" aria-label="最近请求">
    <header class="group-head">
      <h3>最近请求 <span class="count">{{ requests.length }}</span></h3>
      <button aria-label="复制最近请求" ...>复制</button>
    </header>
    <p v-if="!requests.length" class="empty">暂无请求记录</p>
    <ul v-else class="rows">
      <li v-for="(item, index) in requests" :key="`req-${item.at}-${index}`" class="row">
        <span class="mono time">{{ at(item.at) }}</span>
        <span class="mono status" :class="item.status >= 400 ? 'is-bad' : 'is-ok'">{{ item.status }}</span>
        <span class="mono duration">{{ formatDuration(item.durationMs) }}</span>
        <span class="mono id">{{ item.requestId || '无 request_id' }}</span>
      </li>
    </ul>
  </section>

  <section class="group" aria-label="最近错误">
    <header ...>
      <h3>最近错误 <span class="count">{{ errors.length }}</span></h3>
      <button aria-label="复制最近错误" ...>复制</button>
    </header>
    <p v-if="!errors.length" class="empty">暂无错误记录</p>
    <ul v-else class="rows">
      <li v-for="(item, index) in errors" :key="`err-${item.at}-${index}`" class="row error-row">
        <span class="mono time">{{ at(item.at) }}</span>
        <span class="mono code">{{ item.code }}</span>
        <span class="message">{{ item.message }}</span>
        <span class="mono id">{{ item.requestId || '无 request_id' }}</span>
      </li>
    </ul>
  </section>

  <section class="group" aria-label="Web Vitals">
    <header ...>
      <h3>Web Vitals <span class="count">{{ vitals.length }}</span></h3>
      <button aria-label="复制 Web Vitals" @click="copy('Web Vitals', vitalsText)">复制</button>
    </header>
    <p v-if="!vitals.length" class="empty">暂无 Web Vitals 记录</p>
    <ul v-else class="rows">
      <li v-for="(item, index) in vitals" :key="`vital-${item.name}-${item.at}-${index}`" class="row">
        <span class="mono time">{{ at(item.at) }}</span>
        <span class="mono name">{{ item.name }}</span>
        <span class="mono value">{{ formatVital(item) }}</span>
      </li>
    </ul>
  </section>

  <div class="foot">
    <button type="button" class="btn" @click="refresh">刷新</button>
    <button type="button" class="btn is-primary" aria-label="关闭诊断抽屉" @click="emit('close')">关闭</button>
  </div>
</el-drawer>
```

注意：`at` 函数名可能与 `<script>` 的 `at` 冲突？没有。但 `at` 作为函数名很通用；命名 `formatAt` 更清晰。

`formatDuration(18)` → '18ms' 好。

Web Vitals 测试断言 '0.125' — formatVital CLS = '0.125'。好。

