import { onMounted, onUnmounted, ref } from 'vue'
...
import DiagnosticsDrawer from '@/components/common/DiagnosticsDrawer.vue'
import { startWebVitals } from '@/utils/web-vitals'

const diagnosticsOpen = ref(false)
let stopWebVitals: (() => void) | null = null

onMounted(() => {
  // 登录后尽早拉取系统信息，导航按 capabilities 置灰。
  if (auth.isAuthenticated) void system.load()
  // Web Vitals 从布局挂载开始采集，卸载时断开 observer。
  stopWebVitals = startWebVitals()
})

onUnmounted(() => {
  stopWebVitals?.()
  stopWebVitals = null
})
```

模板：SideNav 加 `@diagnostics="diagnosticsOpen = true"`；在 `.app-shell` 内（或末尾）挂 `<DiagnosticsDrawer :open="diagnosticsOpen" @close="diagnosticsOpen = false" />`。抽屉 append-to-body 所以位置无所谓，放在 scrim 之后、main 之后均可。放在根 div 末尾。

注意 `onMounted` 中测试环境 AppLayout 无测试。startWebVitals 在真实浏览器工作；在单元环境无影响。

编辑。

